from math import gcd

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def count_exactly_one(x, n, m):
    cnt_n = x // n
    cnt_m = x // m
    cnt_both = x // lcm(n, m)
    return cnt_n + cnt_m - 2 * cnt_both

def find_kth_smallest_divisible(n: int, m: int, k: int) -> int:
    l = 1
    r = 10**18

    while r - l > 1:
        mid = (l + r) // 2
        cnt = count_exactly_one(mid, n, m)
        if cnt >= k:
            r = mid
        else:
            l = mid

    return r

n, m, k = map(int, input().split())
print(find_kth_smallest_divisible(n, m, k))
